import React, { useEffect, useState } from 'react';
import axios           from 'axios';
import { useNavigate } from 'react-router-dom';

type DR = { _id:string; name:string; email:string; phone:string; address:string; isAvailable:boolean };

export default function DriverList() {
  const [dr, setDr] = useState<DR[]>([]);
  const nav = useNavigate();

  useEffect(()=>{
    axios.get(`${process.env.REACT_APP_API_URL}/api/drivers`)
         .then(r=>setDr(r.data));
  },[]);

  const del = async (id:string)=>{
    if(!confirm('Delete?'))return;
    await axios.delete(`${process.env.REACT_APP_API_URL}/api/drivers/${id}`);
    setDr(dr.filter(x=>x._id!==id));
  };

  return (
    <div style={{padding:20}}>
      <h3>Drivers</h3>
      <button onClick={()=>nav('/analytics')}>Analytics</button>
      <table style={{width:'100%',marginTop:10}}>
        <thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Address</th><th>Avail</th><th>Actions</th></tr></thead>
        <tbody>
          {dr.map(d=>
            <tr key={d._1d}>
              <td>{d.name}</td><td>{d.email}</td><td>{d.phone}</td><td>{d.address}</td>
              <td>{d.isAvailable?'Yes':'No'}</td>
              <td>
                <button onClick={()=>nav(`/edit-driver/${d._id}`)}>✏️</button>
                <button onClick={()=>del(d._id)}>🗑️</button>
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}
